      margin-bottom: 0.5rem;
    }

    .card {
      background: rgba(8, 19, 48, 0.96);
      border-radius: 0.9rem;
      padding: 1rem 1.1rem;
      margin-bottom: 1rem;
      box-shadow: 0 14px 35px rgba(0, 0, 0, 0.4);
      border: 1px solid rgba(77, 132, 255, 0.22);
    }

    label {
      display: block;
      font-size: 0.85rem;
      margin-bottom: 0.15rem;
      opacity: 0.9;
    }

    input[type="text"],
