    [46, "Pushing Upward"],
    [47, "Oppression"],
    [48, "The Well"],
    [49, "Revolution"],
    [50, "The Cauldron"],
    [51, "The Arousing"],
    [52, "Keeping Still"],
    [53, "Development"],
    [54, "The Marrying Maiden"],
    [55, "Abundance"],
    [56, "The Wanderer"],
    [57, "Gentle Penetration"],
    [58, "Joyous Lake"],
    [59, "Dispersion"],
    [60, "Limitation"],
    [61, "Inner Truth"],
    [62, "Small Exceeding"],
    [63, "After Completion"],
    [64, "Before Completion"],
  ];

  // --- Utility functions --------------------------------------------------------

  function rollDie(sides) {
    return Math.floor(Math.random() * sides) + 1;
  }

  function simpleHash(str) {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      hash = (hash * 31 + str.charCodeAt(i)) >>> 0;
    }
    return hash.toString(16);
  }

  function makeSeed(d4, d6, d12, d20, isoTimestamp) {
    const raw = `${d4}-${d6}-${d12}-${d20}-${isoTimestamp}`;
    // Return numeric version for modulo operations
    const hex = simpleHash(raw);
    return parseInt(hex.slice(0, 8), 16) >>> 0;
  }

  function reduceNumerology(n) {
    let value = Math.abs(n);
    while (value > 9 && value !== 11 && value !== 22 && value !== 33) {
      let sum = 0;
      const s = String(value);
      for (let i = 0; i < s.length; i++) sum += Number(s[i]);
      value = sum;
    }
    return value;
  }

  function loadProfile() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY_PROFILE);
      if (!raw) return { name: "", sun: "", moon: "", rising: "" };
      const p = JSON.parse(raw);
      return {
        name: p.name || "",
        sun: p.sun || "",
        moon: p.moon || "",
        rising: p.rising || "",
      };
    } catch {
      return { name: "", sun: "", moon: "", rising: "" };
    }
  }

  function saveProfile(profile) {
    localStorage.setItem(STORAGE_KEY_PROFILE, JSON.stringify(profile));
  }

  function loadReadings() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY_READINGS);
      if (!raw) return [];
      return JSON.parse(raw);
    } catch {
      return [];
    }
  }

  function saveReadings(readings) {
    localStorage.setItem(STORAGE_KEY_READINGS, JSON.stringify(readings));
  }

  // --- Plugins -----------------------------------------------------------------

  function tarotPlugin(ctx) {
    const { seed } = ctx;
    const index = seed % TAROT_CARDS.length;
    const card = TAROT_CARDS[index];
    const note = TAROT_NOTES[card] || "";
    return {
      name: "tarot",
      label: "Tarot echo",
      version: "1.0",
      payload: {
        cards: [card],
        notes: note,
      },
    };
  }

  function runesPlugin(ctx) {
    const { seed } = ctx;
    const index = (seed * 7) % RUNES.length;
    const rune = RUNES[index];
    const note = RUNES_NOTES[rune] || "";
    return {
      name: "runes",
      label: "Rune echo",
      version: "1.0",
      payload: {
        runes: [rune],
        notes: note,
      },
    };
  }

  function ichingPlugin(ctx) {
    const { seed } = ctx;
    const index = (seed * 13) % ICHING_HEXAGRAMS.length;
    const [num, name] = ICHING_HEXAGRAMS[index];
    return {
      name: "iching",
      label: "I Ching echo",
      version: "1.0",
      payload: {
        hexagram: { number: num, name },
        notes: "",
      },
    };
  }

  function numerologyPlugin(ctx) {
    const { seed, timestamp, question } = ctx;
    const date = new Date(timestamp);
    const base =
      date.getFullYear() + (date.getMonth() + 1) + date.getDate() + seed;
    const qSum = question
      ? question
          .toLowerCase()
          .replace(/[^a-z]/g, "")
          .split("")
          .reduce((acc, ch) => acc + (ch.charCodeAt(0) - 96), 0)
      : 0;
    const total = base + qSum;
    const num = reduceNumerology(total);
    const meaningMap = {
      1: "Initiation, self-definition, leadership.",
      2: "Partnership, balance, listening.",
      3: "Expression, creativity, synthesis.",
      4: "Structure, foundations, discipline.",
      5: "Change, freedom, adaptation.",
      6: "Responsibility, care, harmonizing.",
      7: "Reflection, inner work, analysis.",
      8: "Power, manifestation, material flow.",
      9: "Completion, compassion, closure.",
      11: "Intuition, inspiration, spiritual insight.",
      22: "Master builder, large-scale impact.",
      33: "Master teacher, service to many.",
    };
    return {
      name: "numerology",
      label: "Numerology echo",
      version: "1.0",
      payload: {
        number: num,
        notes: meaningMap[num] || "",
      },
    };
  }

  function astroPlugin(ctx) {
    const { haloCore, profile } = ctx;
    const sun = profile.sun || "";
    const moon = profile.moon || "";
    const rising = profile.rising || "";

    let focusHint = "";
    if (haloCore.axis === 1) focusHint = "Ground this in your body and daily life.";
    if (haloCore.axis === 2) focusHint = "Pay attention to the stories you tell.";
    if (haloCore.axis === 3) focusHint = "Center your relationships and feelings.";
    if (haloCore.axis === 4) focusHint =
      "Treat this as ritual / magic / domain-level work.";

    return {
      name: "astro",
      label: "Astro echo",
      version: "1.0",
      payload: {
        sun,
        moon,
        rising,
        notes: focusHint,
      },
    };
  }

  const PLUGINS = [
    tarotPlugin,
    runesPlugin,
    ichingPlugin,
    numerologyPlugin,
    astroPlugin,
  ];

  // --- Synthesis ---------------------------------------------------------------

  function synthesize(haloCore, pluginResults, question, profile) {
    const axisLabel = AXIS_MAP[haloCore.axis] || "Unknown axis";
    const vectorLabel = VECTOR_MAP[haloCore.vector] || "Unknown vector";
    const timelineLabel =
      TIMELINE_MAP[haloCore.timeline] || "Unspecified timeframe";

    const tarot = pluginResults.find((p) => p.name === "tarot");
    const runes = pluginResults.find((p) => p.name === "runes");
    const iching = pluginResults.find((p) => p.name === "iching");
    const num = pluginResults.find((p) => p.name === "numerology");
    const astro = pluginResults.find((p) => p.name === "astro");

    const tarotCard = tarot ? tarot.payload.cards.join(", ") : "";
    const runeName = runes ? runes.payload.runes.join(", ") : "";
    const hex =
      iching && iching.payload.hexagram
        ? `Hex ${iching.payload.hexagram.number} – ${iching.payload.hexagram.name}`
        : "";
    const numStr = num ? String(num.payload.number) : "";
    const astroBrief =
      astro && (astro.payload.sun || astro.payload.moon || astro.payload.rising)
        ? `Sun ${astro.payload.sun || "?"}, Moon ${
            astro.payload.moon || "?"
          }, Rising ${astro.payload.rising || "?"}`
        : "";

    const who = profile.name ? `for ${profile.name}` : "for you";

    const coreMessage =
      `This reading ${who} highlights **${axisLabel}** as the main arena, ` +
      `with a **${vectorLabel}** pattern playing out over **${timelineLabel}**. ` +
      `The archetype in play is **${haloCore.archetype}**.`;

    const echoMessage =
      `Echo signals: Tarot shows **${tarotCard}**, the rune points to **${runeName}**, ` +
      `the I Ching offers **${hex}**, and numerology condenses this into **${numStr}**. ` +
      (astroBrief ? `Astro overlay: ${astroBrief}. ` : "");

    const qLine = question
      ? `In relation to your question – “${question}” – treat this as guidance, not a fixed sentence. `
      : "";

    const suggested = [];
    switch (haloCore.vector) {
      case 1:
        suggested.push("Take one small, concrete action in the next 24 hours.");
        break;
      case 2:
        suggested.push("Identify what is already working and feed it more energy.");
        break;
      case 3:
        suggested.push("Stabilize by simplifying and reducing noise around this issue.");
        break;
      case 4:
        suggested.push("Consciously release one attachment or expectation that no longer fits.");
        break;
      case 5:
        suggested.push(
          "Transmute by turning a perceived weakness or wound into a skill or boundary."
        );
        break;
      case 6:
        suggested.push(
          "Witness without forcing change; gather information and let patterns reveal themselves."
        );
        break;
      default:
        suggested.push("Notice what this brings up in you and journal it.");
    }

    const comfortRating =
      haloCore.vector === 1 || haloCore.vector === 2 || haloCore.vector === 3
        ? 7
        : haloCore.vector === 6
        ? 5
        : 4; // release / transmute often feel harder

    return {
      core_message: coreMessage + " " + echoMessage + qLine,
      suggested_actions: suggested,
      comfort_rating: comfortRating,
    };
  }

  // --- HALO kernel + reading creation -----------------------------------------

  function createReading(question, profile) {
    const timestamp = new Date().toISOString();
    const d4 = rollDie(4);
    const d6 = rollDie(6);
    const d12 = rollDie(12);
    const d20 = rollDie(20);
    const axis = ((d4 - 1) % 4) + 1;
    const vector = ((d6 - 1) % 6) + 1;
    const timeline = ((d12 - 1) % 12) + 1;
    const archetypeIndex = (d20 - 1) % ARCHETYPES.length;
    const archetype = ARCHETYPES[archetypeIndex];

    const seed = makeSeed(d4, d6, d12, d20, timestamp);

    const haloCore = {
      axis,
      vector,
      timeline,
      archetypeIndex,
      archetype,
      dice: { d4, d6, d12, d20 },
    };

    const ctx = {
      seed,
      haloCore,
      profile,
      question: question || "",
      timestamp,
    };

    const pluginResults = PLUGINS.map((fn) => fn(ctx));
    const summary = synthesize(haloCore, pluginResults, question, profile);

    const existing = loadReadings();
    const prevHash =
      existing.length && existing[existing.length - 1].chain
        ? existing[existing.length - 1].chain.hash
        : null;

    const id =
      Date.now().toString(36) +
      "-" +
      Math.random().toString(16).slice(2, 8);

    const hash = simpleHash(
      JSON.stringify({
        id,
        question,
        haloCore,
        pluginResults,
        timestamp,
        prevHash,
      })
    );

    const reading = {
      id,
      user: profile,
      question: question || "",
      created_at: timestamp,
      seed,
      halo: haloCore,
      plugins: pluginResults,
      summary,
      chain: {
        prev_hash: prevHash,
        hash,
      },
    };

    existing.push(reading);
    saveReadings(existing);

    return reading;
  }

  // --- UI Rendering ------------------------------------------------------------

  function renderCurrentReading(reading) {
    const container = document.getElementById("current-reading");
    if (!reading) {
      container.innerHTML = "";
      return;
    }

    const halo = reading.halo;
    const axisLabel = AXIS_MAP[halo.axis];
    const vectorLabel = VECTOR_MAP[halo.vector];
    const timelineLabel = TIMELINE_MAP[halo.timeline];
    const dice = halo.dice;
    const s = reading.summary;

    const tarot = reading.plugins.find((p) => p.name === "tarot");
    const runes = reading.plugins.find((p) => p.name === "runes");
    const iching = reading.plugins.find((p) => p.name === "iching");
    const num = reading.plugins.find((p) => p.name === "numerology");
    const astro = reading.plugins.find((p) => p.name === "astro");

    container.innerHTML = `
      <div class="reading-grid">
        <div class="reading-block">
          <h3>HALO Core</h3>
          <div>
            <div class="pill mono">Axis: ${axisLabel}</div>
            <div class="pill mono">Vector: ${vectorLabel}</div>
            <div class="pill mono">Timeline: ${timelineLabel}</div>
            <div class="pill mono">Archetype: ${halo.archetype}</div>
          </div>
          <p class="mono" style="margin-top:0.4rem;">
            Dice: d4=${dice.d4}, d6=${dice.d6}, d12=${dice.d12}, d20=${dice.d20}
          </p>
        </div>

        <div class="reading-block">
          <h3>Meta Synthesis</h3>
          <p>${s.core_message}</p>
          <ul>
            ${s.suggested_actions
              .map((a) => `<li>${a}</li>`)
              .join("")}
          </ul>
          <p class="muted">Comfort rating: ${s.comfort_rating}/10 (higher = gentler).</p>
        </div>

        <div class="reading-block">
          <h3>Plugins</h3>
          <details>
            <summary>Tarot</summary>
            <p><strong>Card(s):</strong> ${
              tarot ? tarot.payload.cards.join(", ") : "—"
            }</p>
            <p class="muted">${tarot && tarot.payload.notes ? tarot.payload.notes : ""}</p>
          </details>
          <details>
            <summary>Runes</summary>
            <p><strong>Rune(s):</strong> ${
              runes ? runes.payload.runes.join(", ") : "—"
            }</p>
            <p class="muted">${runes && runes.payload.notes ? runes.payload.notes : ""}</p>
          </details>
          <details>
            <summary>I Ching</summary>
            <p><strong>Hexagram:</strong> ${
              iching
                ? `${iching.payload.hexagram.number} – ${iching.payload.hexagram.name}`
                : "—"
            }</p>
          </details>
          <details>
            <summary>Numerology</summary>
            <p><strong>Number:</strong> ${
              num ? num.payload.number : "—"
            }</p>
            <p class="muted">${num && num.payload.notes ? num.payload.notes : ""}</p>
          </details>
          <details>
            <summary>Astro</summary>
            <p>${astro ? astro.payload.notes : ""}</p>
            ${
              astro &&
              (astro.payload.sun || astro.payload.moon || astro.payload.rising)
                ? `<p class="muted">Sun ${astro.payload.sun || "?"}, Moon ${
                    astro.payload.moon || "?"
                  }, Rising ${astro.payload.rising || "?"}</p>`
                : ""
            }
          </details>
        </div>
      </div>
      <p class="timestamp">Reading ID: <span class="mono">${
        reading.id
      }</span> – Hash: <span class="mono">${reading.chain.hash}</span></p>
    `;
  }

  function renderHistory() {
    const historyEl = document.getElementById("history");
    const readings = loadReadings();

    if (!readings.length) {
      historyEl.innerHTML = '<p class="muted">No readings yet.</p>';
      return;
    }

    const rows = readings
      .slice()
      .reverse()
      .map((r) => {
        const date = new Date(r.created_at);
        const halo = r.halo;
        return `
          <tr>
            <td class="timestamp">${date.toLocaleString()}</td>
            <td>${AXIS_MAP[halo.axis] || ""}</td>
            <td>${VECTOR_MAP[halo.vector] || ""}</td>
            <td>${TIMELINE_MAP[halo.timeline] || ""}</td>
            <td>${halo.archetype}</td>
            <td class="mono">${r.chain.hash.slice(0, 8)}…</td>
          </tr>
        `;
      })
      .join("");

    historyEl.innerHTML = `
      <table>
        <thead>
          <tr>
            <th>When</th>
            <th>Axis</th>
            <th>Vector</th>
            <th>Timeline</th>
            <th>Archetype</th>
            <th>Hash</th>
          </tr>
        </thead>
        <tbody>
          ${rows}
        </tbody>
      </table>
      <button id="export-readings">Export readings JSON</button>
    `;

    const exportBtn = document.getElementById("export-readings");
    if (exportBtn) {
      exportBtn.addEventListener("click", () => {
        const blob = new Blob([JSON.stringify(readings, null, 2)], {
          type: "application/json",
        });
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = "halo_readings.json";
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
      });
    }
  }

  // --- Init + event wiring -----------------------------------------------------

  function init() {
    const profile = loadProfile();
    document.getElementById("profile-name").value = profile.name;
    document.getElementById("profile-sun").value = profile.sun;
    document.getElementById("profile-moon").value = profile.moon;
    document.getElementById("profile-rising").value = profile.rising;

    document
      .getElementById("save-profile")
      .addEventListener("click", () => {
        const p = {
          name: document.getElementById("profile-name").value.trim(),
          sun: document.getElementById("profile-sun").value.trim(),
          moon: document.getElementById("profile-moon").value.trim(),
          rising: document.getElementById("profile-rising").value.trim(),
        };
        saveProfile(p);
      });

    document.getElementById("roll-btn").addEventListener("click", () => {
      const q = document.getElementById("question").value.trim();
      const currentProfile = loadProfile();
      const reading = createReading(q, currentProfile);
      renderCurrentReading(reading);
      renderHistory();
    });

    renderHistory();
  }

  // Script is at end of body, DOM is ready.
  init();
})();
```

