          <p class="muted">Comfort rating: ${s.comfort_rating}/10 (higher = gentler).</p>
        </div>

        <div class="reading-block">
          <h3>Plugins</h3>
          <details>
            <summary>Tarot</summary>
            <p><strong>Card(s):</strong> ${
              tarot ? tarot.payload.cards.join(", ") : "—"
            }</p>
            <p class="muted">${tarot && tarot.payload.notes ? tarot.payload.notes : ""}</p>
          </details>
          <details>
            <summary>Runes</summary>
            <p><strong>Rune(s):</strong> ${
              runes ? runes.payload.runes.join(", ") : "—"
            }</p>
            <p class="muted">${runes && runes.payload.notes ? runes.payload.notes : ""}</p>
          </details>
          <details>
            <summary>I Ching</summary>
            <p><strong>Hexagram:</strong> ${
              iching
                ? `${iching.payload.hexagram.number} – ${iching.payload.hexagram.name}`
                : "—"
            }</p>
          </details>
          <details>
            <summary>Numerology</summary>
            <p><strong>Number:</strong> ${
              num ? num.payload.number : "—"
            }</p>
            <p class="muted">${num && num.payload.notes ? num.payload.notes : ""}</p>
          </details>
          <details>
            <summary>Astro</summary>
            <p>${astro ? astro.payload.notes : ""}</p>
            ${
              astro &&
              (astro.payload.sun || astro.payload.moon || astro.payload.rising)
                ? `<p class="muted">Sun ${astro.payload.sun || "?"}, Moon ${
                    astro.payload.moon || "?"
                  }, Rising ${astro.payload.rising || "?"}</p>`
                : ""
            }
          </details>
        </div>
      </div>
      <p class="timestamp">Reading ID: <span class="mono">${
        reading.id
      }</span> – Hash: <span class="mono">${reading.chain.hash}</span></p>
    `;
  }

  function renderHistory() {
    const historyEl = document.getElementById("history");
    const readings = loadReadings();

    if (!readings.length) {
      historyEl.innerHTML = '<p class="muted">No readings yet.</p>';
      return;
    }

    const rows = readings
      .slice()
      .reverse()
      .map((r) => {
        const date = new Date(r.created_at);
        const halo = r.halo;
        return `
          <tr>
            <td class="timestamp">${date.toLocaleString()}</td>
            <td>${AXIS_MAP[halo.axis] || ""}</td>
            <td>${VECTOR_MAP[halo.vector] || ""}</td>
            <td>${TIMELINE_MAP[halo.timeline] || ""}</td>
            <td>${halo.archetype}</td>
            <td class="mono">${r.chain.hash.slice(0, 8)}…</td>
          </tr>
        `;
      })
      .join("");

    historyEl.innerHTML = `
      <table>
        <thead>
          <tr>
            <th>When</th>
            <th>Axis</th>
            <th>Vector</th>
            <th>Timeline</th>
            <th>Archetype</th>
            <th>Hash</th>
          </tr>
        </thead>
        <tbody>
          ${rows}
        </tbody>
      </table>
      <button id="export-readings">Export readings JSON</button>
    `;

    const exportBtn = document.getElementById("export-readings");
    if (exportBtn) {
      exportBtn.addEventListener("click", () => {
        const blob = new Blob([JSON.stringify(readings, null, 2)], {
          type: "application/json",
        });
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = "halo_readings.json";
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
      });
    }
  }

  function init() {
    const profile = loadProfile();
    document.getElementById("profile-name").value = profile.name;
    document.getElementById("profile-sun").value = profile.sun;
    document.getElementById("profile-moon").value = profile.moon;
    document.getElementById("profile-rising").value = profile.rising;

    document.getElementById("save-profile").addEventListener("click", () => {
      const p = {
        name: document.getElementById("profile-name").value.trim(),
        sun: document.getElementById("profile-sun").value.trim(),
        moon: document.getElementById("profile-moon").value.trim(),
        rising: document.getElementById("profile-rising").value.trim(),
      };
      saveProfile(p);
    });

    document.getElementById("roll-btn").addEventListener("click", () => {
      const q = document.getElementById("question").value.trim();
      const currentProfile = loadProfile();
      const reading = createReading(q, currentProfile);
      renderCurrentReading(reading);
      renderHistory();
    });

    renderHistory();
  }

  init();
})();
```

